from dataclasses import dataclass
from typing import Callable


# A toy node. Don't change it. eq=False makes == and hash() compare identity, like OCaml's ==.
@dataclass(eq=False)
class Node:
    id: int
    op: str
    src: list["Node"]


def create() -> Callable[[str, list[Node]], Node]:
    """Return a fresh make function with its own table.
    make(op, src) returns the SAME node (is) when called again with the same op
    and the same source nodes, and otherwise a new node with the next id: 0, 1, 2, ..."""

    def make(op: str, src: list[Node]) -> Node:
        return Node(0, op, src)

    return make
